def clamp_scale(value: Any) -> int:
    """Приводит размер персонажа к целому числу в допустимых границах."""
    try:
        v = int(round(float(value)))
    except (TypeError, ValueError):
        v = SPRITE_SCALE
    return max(AVATAR_SCALE_MIN, min(AVATAR_SCALE_MAX, v))


