def require(module: str, pip_name: Optional[str] = None):
    """Ленивый импорт: если модуля нет — понятная ошибка в логе вместо падения."""
    try:
        return importlib.import_module(module)
    except ImportError as exc:
        raise RuntimeError(f"Не установлен модуль «{module}». Установите: pip install {pip_name or module}") from exc


def extract_json(text: str) -> Optional[dict]:
    """Достаёт JSON-объект из ответа модели, даже если вокруг есть лишний текст."""
    text = (text or "").strip()
    match = re.search(r"\{.*\}", text, re.S)
    for candidate in (text, match.group(0) if match else ""):
        if not candidate:
            continue
        try:
            data = json.loads(candidate)
            if isinstance(data, dict):
                return data
        except json.JSONDecodeError:
            continue
    return None


def clean_text(text: str, limit: int = 450) -> str:
    """Убирает markdown и ссылки, обрезает длинный текст (для озвучки и пузыря)."""
    text = re.sub(r"```.*?```", " ", text, flags=re.S)
    text = re.sub(r"https?://\S+", " ", text)
    text = re.sub(r"[*_#`>~|]", "", text)
    text = re.sub(r"\s+", " ", text).strip()
    if len(text) > limit:
        cut = text[:limit]
        end = max(cut.rfind(". "), cut.rfind("! "), cut.rfind("? "))
        text = cut[: end + 1] if end > 80 else cut
    return text


def timestamp() -> str:
    return datetime.now().strftime("%Y%m%d_%H%M%S")


def init_com() -> None:
    """SAPI5 (pyttsx3) в потоках требует инициализации COM."""
    for name in ("pythoncom", "comtypes"):
        try:
            importlib.import_module(name).CoInitialize()
            return
        except Exception:
            continue


def install_global_hooks(log: Logger) -> None:
    """Необработанные исключения (в т.ч. из потоков) попадают в журнал/панель."""
    def hook(exc_type, exc, tb) -> None:
        log.error("Необработанная ошибка:\n" + "".join(traceback.format_exception(exc_type, exc, tb)))

    sys.excepthook = hook
    threading.excepthook = lambda a: hook(a.exc_type, a.exc_value, a.exc_traceback)


def work_area() -> tuple[int, int, int, int]:
    """Рабочая область экрана без панели задач (left, top, right, bottom)."""
    class RECT(ctypes.Structure):
        _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                    ("right", ctypes.c_long), ("bottom", ctypes.c_long)]
    rect = RECT()
    if ctypes.windll.user32.SystemParametersInfoW(0x0030, 0, ctypes.byref(rect), 0):  # SPI_GETWORKAREA
        return rect.left, rect.top, rect.right, rect.bottom
    return 0, 0, 1920, 1040


