#  Диски и индекс программ
# ══════════════════════════════════════════════════════════════════════════════
@dataclass
class DriveInfo:
    root: str        # например "C:\\"
    label: str       # локальный / съёмный / ...
    kind: int        # код GetDriveTypeW
    total: int
    free: int

    @property
    def scannable(self) -> bool:
        return self.kind in (2, 3)  # съёмный и локальный диски

    def describe(self) -> str:
        gb = 1024 ** 3
        return (f"{self.root.rstrip(chr(92))} {self.label}, свободно "
                f"{self.free / gb:.0f} ГБ из {self.total / gb:.0f} ГБ")


class DriveScanner:
    """Знает, какие диски подключены к компьютеру (через WinAPI, без сторонних библиотек)."""

    TYPES = {2: "съёмный", 3: "локальный", 4: "сетевой", 5: "оптический", 6: "RAM-диск"}

    @classmethod
    def drives(cls) -> list[DriveInfo]:
        mask = ctypes.windll.kernel32.GetLogicalDrives()
        result: list[DriveInfo] = []
        for i in range(26):
            if not mask & (1 << i):
                continue
            root = f"{chr(65 + i)}:\\"
            kind = ctypes.windll.kernel32.GetDriveTypeW(root)
            if kind not in cls.TYPES:
                continue
            try:
                usage = shutil.disk_usage(root)
                total, free = usage.total, usage.free
            except OSError:  # оптический привод без диска и т.п.
                total = free = 0
            result.append(DriveInfo(root, cls.TYPES[kind], kind, total, free))
        return result

    @classmethod
    def lines(cls) -> list[str]:
        return [d.describe() for d in cls.drives()]


@dataclass
class AppEntry:
    name: str
    path: str
    kind: str        # "shortcut" (ярлык из меню «Пуск» / рабочего стола) или "exe"

    @property
    def key(self) -> str:
        return AppIndex.normalize(self.name)


class AppLauncher:
    """Открывает программы, ярлыки, папки и файлы средствами Windows."""

    @staticmethod
    def open(path: str) -> None:
        os.startfile(path)  # type: ignore[attr-defined]  # Windows-only


class AppIndex:
    """
    Индекс программ: ярлыки из меню «Пуск» и рабочих столов + .exe на всех локальных дисках.
    Строится в фоне, сохраняется в apps_index.json, чтобы не сканировать диски при каждом запуске.
    """

    STALE_HOURS = 24
    MAX_DEPTH = 5
    MAX_FILES = 60000
    SKIP_DIRS = {"windows", "$recycle.bin", "system volume information", "appdata", "node_modules",
                 ".git", "__pycache__", "site-packages", "venv", ".venv", "temp", "winsxs", "drivers",
                 "recovery", "perflogs", "$windows.~bt", "$windows.~ws", "config.msi"}
    SKIP_EXE = ("unins", "uninst", "setup", "update", "helper", "crash", "install", "redist",
                "vcredist", "dxsetup", "repair", "updater", "service")

    def __init__(self, settings: Settings):
        self.settings = settings
        self._entries: dict[str, AppEntry] = {}
        self._lock = threading.Lock()
        self.scanning = False
        self.scanned_at: Optional[float] = None
        self._load()

    # ── хранение ─────────────────────────────────────────────────────────────
    @staticmethod
    def normalize(text: str) -> str:
        text = text.lower().strip().strip('"')
        text = re.sub(r"\.(exe|lnk)$", "", text)
        return re.sub(r"[^\w]+", " ", text).strip()

    @property
    def count(self) -> int:
        return len(self._entries)

    def _load(self) -> None:
        try:
            data = json.loads(APPS_INDEX_PATH.read_text("utf-8"))
            self.scanned_at = data.get("scanned_at")
            self._entries = {e["key"]: AppEntry(e["name"], e["path"], e["kind"]) for e in data.get("apps", [])}
        except (OSError, ValueError, KeyError):
            pass

    def _save(self) -> None:
        payload = {"scanned_at": self.scanned_at,
                   "apps": [{"name": e.name, "path": e.path, "kind": e.kind} for e in self._entries.values()]}
        APPS_INDEX_PATH.write_text(json.dumps(payload, ensure_ascii=False), "utf-8")

    def is_stale(self) -> bool:
        if not self.scanned_at or not self._entries:
            return True
        return time.time() - self.scanned_at > self.STALE_HOURS * 3600

    # ── поиск ────────────────────────────────────────────────────────────────
    def find(self, query: str) -> Optional[AppEntry]:
        q = self.normalize(query)
        if not q:
            return None
        with self._lock:
            entries = self._entries
        if q in entries:
            return entries[q]
        contains = [k for k in entries if q in k]
        if contains:
            return entries[min(contains, key=len)]
        close = difflib.get_close_matches(q, list(entries), n=1, cutoff=0.72)
        return entries[close[0]] if close else None

    # ── сканирование ─────────────────────────────────────────────────────────
    def _walk(self, root: str, max_depth: int, want_ext: str, kind: str, out: list[AppEntry]) -> None:
        stack = [(root, 0)]
        while stack and len(out) < self.MAX_FILES:
            path, depth = stack.pop()
            try:
                it = os.scandir(path)
            except OSError:
                continue
            with it:
                for e in it:
                    try:
                        lname = e.name.lower()
                        if e.is_dir(follow_symlinks=False):
                            if depth < max_depth and lname not in self.SKIP_DIRS:
                                stack.append((e.path, depth + 1))
                        elif lname.endswith(want_ext):
                            if want_ext == ".exe" and any(s in lname for s in self.SKIP_EXE):
                                continue
                            out.append(AppEntry(e.name[: -len(want_ext)], e.path, kind))
                    except OSError:
                        continue

    def _shortcut_roots(self) -> list[str]:
        return [
            os.path.expandvars(r"%ProgramData%\Microsoft\Windows\Start Menu\Programs"),
            os.path.expandvars(r"%APPDATA%\Microsoft\Windows\Start Menu\Programs"),
            os.path.expandvars(r"%USERPROFILE%\Desktop"),
            os.path.expandvars(r"%PUBLIC%\Desktop"),
        ]

    def scan_async(self, log: Logger) -> None:
        if self.scanning:
            return
        threading.Thread(target=self.scan, args=(log,), daemon=True, name="pcfer-scan").start()

    def scan(self, log: Logger) -> None:
        self.scanning = True
        try:
            found: list[AppEntry] = []
            for root in self._shortcut_roots():
                if os.path.isdir(root):
                    self._walk(root, 6, ".lnk", "shortcut", found)
            for drive in DriveScanner.drives():
                if drive.scannable:
                    log.info(f"Сканирую диск {drive.root} …")
                    self._walk(drive.root, self.MAX_DEPTH, ".exe", "exe", found)
            for extra in self.settings.extra_dirs:
                if os.path.isdir(extra):
                    self._walk(extra, self.MAX_DEPTH, ".exe", "exe", found)
                    self._walk(extra, self.MAX_DEPTH, ".lnk", "shortcut", found)

            entries: dict[str, AppEntry] = {}
            for app in found:  # ярлыки идут первыми и не перекрываются exe с тем же именем
                key = app.key
                if key and key not in entries:
                    entries[key] = app
            with self._lock:
                self._entries = entries
            self.scanned_at = time.time()
            self._save()
            log.ok(f"Индекс программ готов: {len(entries)} шт.")
        except Exception:
            log.exception("Ошибка сканирования программ")
        finally:
            self.scanning = False


# ══════════════════════════════════════════════════════════════════════════════
#  LLM-провайдеры
# ══════════════════════════════════════════════════════════════════════════════
class LLMProvider(ABC):
    name: str = ""

    def __init__(self, settings: Settings):
        self.settings = settings

    @property
    def model(self) -> str:
        return self.settings.models[self.name]

    @property
    def vision_model(self) -> str:
        return self.settings.vision_models[self.name]

    @abstractmethod
    def chat(self, messages: list[dict], json_mode: bool = False) -> str: ...

    @abstractmethod
    def vision(self, prompt: str, image_path: Path, json_mode: bool = False) -> str: ...

    @classmethod
    @abstractmethod
    def list_models(cls) -> list[str]: ...


class OllamaProvider(LLMProvider):
    name = "ollama"

    def chat(self, messages, json_mode=False):
        kwargs = {"format": "json"} if json_mode else {}
        resp = require("ollama").chat(model=self.model, messages=messages, **kwargs)
        return resp["message"]["content"]

    def vision(self, prompt, image_path, json_mode=False):
        kwargs = {"format": "json"} if json_mode else {}
        resp = require("ollama").chat(
            model=self.vision_model,
            messages=[{"role": "user", "content": prompt, "images": [str(image_path)]}],
            **kwargs,
        )
        return resp["message"]["content"]

    @classmethod
    def list_models(cls) -> list[str]:
        names = []
        for m in require("ollama").list()["models"]:
            try:
                names.append(m["model"])
            except (KeyError, TypeError):
                names.append(m["name"])
        return sorted(names)


class G4FProvider(LLMProvider):
    name = "g4f"
    FALLBACK_MODELS = ["gpt-4o-mini", "gpt-4o", "gpt-4", "deepseek-v3", "llama-3.3-70b", "gemini-2.0-flash"]

    @staticmethod
    def _client():
        return require("g4f.client", "g4f").Client()

    def chat(self, messages, json_mode=False):
        resp = self._client().chat.completions.create(model=self.model, messages=messages)
        return resp.choices[0].message.content

    def vision(self, prompt, image_path, json_mode=False):
        client = self._client()
        msgs = [{"role": "user", "content": prompt}]
        with open(image_path, "rb") as f:
            try:
                resp = client.chat.completions.create(model=self.vision_model, messages=msgs, image=f)
            except TypeError:  # новые версии g4f: images=[[data, name]]
                f.seek(0)
                resp = client.chat.completions.create(
                    model=self.vision_model, messages=msgs, images=[[f.read(), Path(image_path).name]])
        return resp.choices[0].message.content

    @classmethod
    def list_models(cls) -> list[str]:
        try:
            names = sorted(require("g4f.models", "g4f").ModelUtils.convert.keys())
            return names or cls.FALLBACK_MODELS
        except Exception:
            return cls.FALLBACK_MODELS


PROVIDERS: dict[str, type[LLMProvider]] = {"ollama": OllamaProvider, "g4f": G4FProvider}


def make_provider(settings: Settings) -> LLMProvider:
    return PROVIDERS[settings.provider](settings)


