def play_mp3(path: Path) -> None:
    """Проигрывает mp3 встроенным в Windows MediaPlayer (блокирует до конца)."""
    script = (
        "Add-Type -AssemblyName presentationCore;"
        "$p = New-Object System.Windows.Media.MediaPlayer;"
        "$p.Open([uri]'" + path.as_uri() + "');"
        "while(-not $p.NaturalDuration.HasTimeSpan){Start-Sleep -Milliseconds 100};"
        "$p.Play();"
        "Start-Sleep -Milliseconds ([int]$p.NaturalDuration.TimeSpan.TotalMilliseconds + 300)"
    )
    subprocess.run(["powershell", "-NoProfile", "-Command", script], creationflags=NO_WINDOW, check=True)


class Speaker(ABC):
    def __init__(self, settings: Settings):
        self.settings = settings

    @abstractmethod
    def speak(self, text: str) -> None: ...


class Pyttsx3Speaker(Speaker):
    @staticmethod
    def list_voices() -> list[tuple[str, str]]:
        init_com()
        engine = require("pyttsx3").init()
        try:
            return [(v.id, v.name) for v in engine.getProperty("voices")]
        finally:
            engine.stop()

    def speak(self, text: str) -> None:
        init_com()
        engine = require("pyttsx3").init()  # новый движок на фразу — стабильнее в потоках
        try:
            if self.settings.voice_id:
                engine.setProperty("voice", self.settings.voice_id)
            engine.setProperty("rate", int(self.settings.speech_rate))
            engine.setProperty("volume", float(self.settings.speech_volume))
            engine.say(text)
            engine.runAndWait()
        finally:
            engine.stop()


class GTTSSpeaker(Speaker):
    def speak(self, text: str) -> None:
        path = Path(tempfile.gettempdir()) / f"pcfer_tts_{time.time_ns()}.mp3"
        try:
            require("gtts", "gTTS").gTTS(text=text, lang=self.settings.language.split("-")[0]).save(str(path))
            play_mp3(path)
        finally:
            path.unlink(missing_ok=True)


class SpeechService:
    """Выбирает движок озвучки по настройкам, при сбое пробует запасной."""

    ENGINES: dict[str, type[Speaker]] = {"pyttsx3": Pyttsx3Speaker, "gtts": GTTSSpeaker}

    def __init__(self, settings: Settings, log: Logger):
        self.settings = settings
        self.log = log

    def speak(self, text: str) -> None:
        text = clean_text(text)
        if not text:
            return
        order = [self.settings.tts_engine] + [e for e in self.ENGINES if e != self.settings.tts_engine]
        for i, engine in enumerate(order):
            try:
                self.ENGINES[engine](self.settings).speak(text)
                return
            except Exception as exc:
                self.log.error(f"Озвучка ({engine}) не сработала: {exc}")
                if i == 0:
                    self.log.warning(f"Пробую запасной движок: {order[1]}")


# ══════════════════════════════════════════════════════════════════════════════
#  Голос: запись с микрофона (sounddevice) и распознавание (SpeechRecognition)
# ══════════════════════════════════════════════════════════════════════════════
class VoiceListener:
    """
    Запись: sounddevice читает микрофон блоками по 30 мс.
    Фраза начинается, когда громкость блока превышает порог речи, и заканчивается
    после PAUSE секунд тишины. Порог калибруется по фоновому шуму при запуске.
    Распознавание: SpeechRecognition (Google) получает готовый кусок звука.
    """

    RATE = 16000
    BLOCK_SEC = 0.03
    PAUSE = 0.8
    NOISE_FACTOR = 2.5
    MIN_THRESHOLD = 250.0

    def __init__(self, settings: Settings, log: Logger):
        self.settings = settings
        self.log = log
        self._sd = None
        self._np = None
        self._sr = None
        self._recognizer = None
        self._stream = None
        self._block = int(self.RATE * self.BLOCK_SEC)
        self._threshold = self.MIN_THRESHOLD

    def open(self) -> None:
        self._sd = require("sounddevice")
        self._np = require("numpy")
        self._sr = require("speech_recognition", "SpeechRecognition")
        self._recognizer = self._sr.Recognizer()
        self._stream = self._sd.InputStream(samplerate=self.RATE, channels=1,
                                            dtype="int16", blocksize=self._block)
        self._stream.start()
        self._calibrate()

    def close(self) -> None:
        if self._stream is not None:
            try:
                self._stream.stop()
                self._stream.close()
            except Exception:
                pass
            self._stream = None

    def _read(self):
        data, _overflow = self._stream.read(self._block)
        return data[:, 0]

    def _rms(self, frame) -> float:
        samples = frame.astype(self._np.float32)
        return float(self._np.sqrt(self._np.mean(samples * samples)))

    def _drain(self) -> None:
        """Выбрасывает накопившийся звук, чтобы слушать «сейчас», а не прошлое."""
        while self._stream.read_available >= self._block:
            self._stream.read(self._block)

    def _calibrate(self) -> None:
        self.log.state("Калибровка микрофона…")
        self._drain()
        levels = sorted(self._rms(self._read()) for _ in range(int(1.0 / self.BLOCK_SEC)))
        noise = levels[len(levels) // 2]
        self._threshold = max(self.MIN_THRESHOLD, noise * self.settings.mic_factor)
        self.log.info(f"Микрофон откалиброван, порог речи: {self._threshold:.0f}")

    def listen(self, timeout: float = 4, phrase_limit: float = 10) -> Optional[str]:
        """Ждёт речь до timeout секунд, записывает фразу до phrase_limit и возвращает текст."""
        self._drain()
        frames: list = []
        started, silence, spoke, waited = False, 0.0, 0.0, 0.0
        while True:
            frame = self._read()
            loud = self._rms(frame) > self._threshold
            if not started:
                waited += self.BLOCK_SEC
                if loud:
                    started = True
                    frames.append(frame)
                    spoke = self.BLOCK_SEC
                elif waited >= timeout:
                    return None
                continue
            frames.append(frame)
            spoke += self.BLOCK_SEC
            silence = 0.0 if loud else silence + self.BLOCK_SEC
            if silence >= self.settings.phrase_pause or spoke >= phrase_limit:
                break
        raw = self._np.concatenate(frames).astype(self._np.int16).tobytes()
        return self._recognize(raw)

    def _recognize(self, raw: bytes) -> Optional[str]:
        sr = self._sr
        audio = sr.AudioData(raw, self.RATE, 2)  # 16 бит = 2 байта на сэмпл
        try:
            return self._recognizer.recognize_google(audio, language=self.settings.language).lower()
        except sr.UnknownValueError:
            return None
        except sr.RequestError as exc:
            self.log.error(f"Сервис распознавания недоступен: {exc}")
            time.sleep(2)
            return None


class TriggerDetector:
    """Ищет слово-триггер (и варианты, как его «слышит» распознавание) во фразе."""

    def __init__(self, settings: Settings):
        self.settings = settings

    @property
    def words(self) -> list[str]:
        raw = [self.settings.trigger, *self.settings.trigger_aliases.split(",")]
        return [w.strip().lower() for w in raw if w.strip()]

    def find(self, text: str) -> Optional[str]:
        """None — триггера нет; строка — то, что сказано после него ('' если ничего)."""
        low = text.lower()
        best: Optional[tuple[int, int]] = None
        for word in self.words:
            idx = low.find(word)
            if idx != -1 and (best is None or idx < best[0]):
                best = (idx, idx + len(word))
        if best is None:
            return None
        return text[best[1]:].strip(" ,.!?:;-")


