class ScreenService:
    def __init__(self, settings: Settings):
        self.settings = settings

    @property
    def out_dir(self) -> Path:
        path = Path(self.settings.output_dir)
        path.mkdir(parents=True, exist_ok=True)
        return path

    def grab(self):
        mss = require("mss")
        image_mod = require("PIL.Image", "pillow")
        with mss.mss() as sct:
            shot = sct.grab(sct.monitors[1])
            return image_mod.frombytes("RGB", shot.size, shot.bgra, "raw", "BGRX")

    def save_screenshot(self) -> Path:
        path = self.out_dir / f"screenshot_{timestamp()}.png"
        self.grab().save(path)
        return path

    def snapshot_for_model(self, max_side: int = 1280) -> Path:
        img = self.grab()
        img.thumbnail((max_side, max_side))
        path = Path(tempfile.gettempdir()) / f"pcfer_view_{time.time_ns()}.png"
        img.save(path)
        return path


class ScreenRecorder:
    FPS = 12

    def __init__(self, screen: ScreenService, log: Logger):
        self.screen = screen
        self.log = log
        self._thread: Optional[threading.Thread] = None
        self._stop = threading.Event()
        self._path: Optional[Path] = None

    @property
    def recording(self) -> bool:
        return self._thread is not None and self._thread.is_alive()

    def start(self) -> Path:
        if self.recording:
            raise RuntimeError("Запись уже идёт")
        for mod, pip in (("cv2", "opencv-python"), ("numpy", None), ("mss", None)):
            require(mod, pip)
        self._path = self.screen.out_dir / f"record_{timestamp()}.mp4"
        self._stop.clear()
        self._thread = threading.Thread(target=self._run, args=(self._path,), daemon=True)
        self._thread.start()
        return self._path

    def stop(self) -> Path:
        if not self.recording:
            raise RuntimeError("Запись сейчас не идёт")
        self._stop.set()
        self._thread.join(timeout=10)
        return self._path

    def _run(self, path: Path) -> None:
        cv2, np, mss = require("cv2", "opencv-python"), require("numpy"), require("mss")
        try:
            with mss.mss() as sct:
                mon = sct.monitors[1]
                writer = cv2.VideoWriter(str(path), cv2.VideoWriter_fourcc(*"mp4v"),
                                         self.FPS, (mon["width"], mon["height"]))
                try:
                    interval = 1 / self.FPS
                    while not self._stop.is_set():
                        t0 = time.time()
                        writer.write(cv2.cvtColor(np.array(sct.grab(mon)), cv2.COLOR_BGRA2BGR))
                        self._stop.wait(max(0.0, interval - (time.time() - t0)))
                finally:
                    writer.release()
        except Exception as exc:
            self.log.error(f"Ошибка записи экрана: {exc}")


class InputDriver:
    """Обёртка над pyautogui. Кириллица вводится через буфер обмена (clip + Ctrl+V)."""

    KEY_ALIASES = {"control": "ctrl", "контрол": "ctrl", "windows": "win", "виндовс": "win",
                   "escape": "esc", "return": "enter", "delete": "del"}

    @property
    def pg(self):
        pg = require("pyautogui")
        pg.FAILSAFE = True  # мышь в левый верхний угол — аварийная остановка
        pg.PAUSE = 0.05
        return pg

    def _norm(self, key: str) -> str:
        key = key.lower().strip()
        return self.KEY_ALIASES.get(key, key)

    def type_text(self, text: str) -> None:
        if text.isascii():
            self.pg.write(text, interval=0.02)
        else:
            subprocess.run(["clip"], input=text.encode("utf-16"), check=True, creationflags=NO_WINDOW)
            self.pg.hotkey("ctrl", "v")

    def hotkey(self, *keys: str) -> None:
        self.pg.hotkey(*[self._norm(k) for k in keys])

    def press(self, key: str) -> None:
        self.pg.press(self._norm(key))

    def click(self, x=None, y=None, button: str = "left", clicks: int = 1) -> None:
        self.pg.click(x=x, y=y, button=button, clicks=clicks)

    def move(self, x: int, y: int) -> None:
        self.pg.moveTo(x, y, duration=0.3)

    def scroll(self, amount: int) -> None:
        self.pg.scroll(amount)

    def screen_size(self) -> tuple[int, int]:
        size = self.pg.size()
        return size.width, size.height


class Context:
    """Общие сервисы, доступные всем действиям."""

    def __init__(self, settings: Settings, log: Logger):
        self.settings = settings
        self.log = log
        self.screen = ScreenService(settings)
        self.recorder = ScreenRecorder(self.screen, log)
        self.input = InputDriver()
        self.apps = AppIndex(settings)

    def vision(self, prompt: str, json_mode: bool = False) -> str:
        image = self.screen.snapshot_for_model()
        try:
            return make_provider(self.settings).vision(prompt, image, json_mode)
        finally:
            image.unlink(missing_ok=True)


