class Presenter:
    """Интерфейс показа состояния. Базовый класс ничего не делает (когда персонаж отключён)."""

    def set_state(self, name: str) -> None: pass
    def say(self, text: str) -> None: pass
    def set_visible(self, visible: bool) -> None: pass
    def set_scale(self, scale: int) -> None: pass
    def event(self, name: str) -> None: pass
    def preview(self, name: str) -> None: pass
    def refresh(self) -> None: pass

    def run(self, quit_evt: threading.Event) -> None:
        """Блокирует главный поток до выхода из сервиса."""
        quit_evt.wait()


class SpriteSheet:
    """Кадры персонажа: из спрайт-листа (сетка) или из папки с PNG-кадрами. Ключи — номера рядов или имена групп."""

    MIN_PIXELS = 12

    def __init__(self, rows: dict, cell_w: int, cell_h: int, box: tuple[int, int, int, int]):
        self.rows = rows
        self.cell_w = max(1, int(cell_w))
        self.cell_h = max(1, int(cell_h))
        self.box = box
        if not self.rows:
            self.rows = {0: [self.placeholder(self.cell_w, self.cell_h)]}

    @classmethod
    def from_sheet(cls, img: Image.Image, cell_w: int, cell_h: int, auto_box: bool) -> "SpriteSheet":
        cw, ch = max(1, int(cell_w)), max(1, int(cell_h))
        rows: dict[int, list[Image.Image]] = {}
        for r in range(img.height // ch):
            row = []
            for c in range(img.width // cw):
                cell = img.crop((c * cw, r * ch, (c + 1) * cw, (r + 1) * ch))
                if sum(cell.getchannel("A").histogram()[1:]) >= cls.MIN_PIXELS:
                    row.append(cell)
            if row:
                rows[r] = row
        if auto_box:
            box = cls._union_box([c for row in rows.values() for c in row], cw, ch)
        else:
            box = AVATAR_BOX
        return cls(rows, cw, ch, box)

    @classmethod
    def from_folder(cls, folder: Path) -> "SpriteSheet":
        """Папка с PNG: файлы name_01.png, name_02.png … — кадры одной группы «name»."""
        frames = []
        for p in sorted(folder.glob("*.png"), key=lambda p: natural_key(p.name)):
            name = re.sub(r"[\s_\-]*\d+$", "", p.stem) or p.stem
            frames.append((name, Image.open(p).convert("RGBA")))
        if not frames:
            raise OSError("в папке нет PNG-кадров")
        w = max(im.width for _, im in frames)
        h = max(im.height for _, im in frames)
        rows: dict[str, list[Image.Image]] = {}
        for name, im in frames:
            canvas = Image.new("RGBA", (w, h), (0, 0, 0, 0))
            canvas.alpha_composite(im)
            rows.setdefault(name, []).append(canvas)
        box = cls._union_box([c for row in rows.values() for c in row], w, h)
        return cls(rows, w, h, box)

    @staticmethod
    def _union_box(cells: list, w: int, h: int, pad: int = 2) -> tuple[int, int, int, int]:
        """Область, в которую попадает персонаж во всех кадрах (чтобы он не прыгал)."""
        boxes = [b for b in (c.getchannel("A").getbbox() for c in cells) if b]
        if not boxes:
            return AVATAR_BOX
        return (max(0, min(b[0] for b in boxes) - pad), max(0, min(b[1] for b in boxes) - pad),
                min(w, max(b[2] for b in boxes) + pad), min(h, max(b[3] for b in boxes) + pad))

    @staticmethod
    def _key(k: Any) -> Any:
        s = str(k).strip()
        return int(s) if s.isdigit() else s

    def frames(self, keys: list) -> list[Image.Image]:
        out: list[Image.Image] = []
        for k in keys:
            out.extend(self.rows.get(self._key(k), []))
        return out

    def fallback(self) -> list[Image.Image]:
        return next(iter(self.rows.values()))

    @staticmethod
    def placeholder(w: int = CELL_W, h: int = CELL_H) -> Image.Image:
        img = Image.new("RGBA", (w, h), (0, 0, 0, 0))
        d = ImageDraw.Draw(img)
        d.ellipse((24, 22, 48, 46), fill=(255, 220, 180, 255), outline=(60, 40, 30, 255), width=2)
        d.ellipse((29, 30, 33, 34), fill=(30, 30, 30, 255))
        d.ellipse((39, 30, 43, 34), fill=(30, 30, 30, 255))
        d.arc((30, 33, 42, 42), 0, 180, fill=(140, 50, 50, 255), width=2)
        return img

    @staticmethod
    def render(cell: Image.Image, box: tuple[int, int, int, int], scale: int) -> Image.Image:
        """Кадр на сплошном цвете-ключе (он станет прозрачным в окне) и увеличенный без сглаживания."""
        part = cell.crop(box)
        bg = Image.new("RGBA", part.size, (255, 0, 254, 255))
        bg.alpha_composite(part)
        return bg.convert("RGB").resize((part.width * scale, part.height * scale), Image.NEAREST)


def natural_key(text: str) -> list:
    """Сортировка «естественным» порядком: name2 идёт раньше name10."""
    return [int(t) if t.isdigit() else t.lower() for t in re.split(r"(\d+)", text)]


def default_sprite_sheet() -> SpriteSheet:
    img = Image.open(io.BytesIO(base64.b64decode(DEFAULT_SPRITE_B64))).convert("RGBA")
    return SpriteSheet.from_sheet(img, CELL_W, CELL_H, auto_box=False)


def load_sprite_sheet(settings: "Settings", log: Optional["Logger"] = None) -> SpriteSheet:
    """Загружает скин из настроек; если не получилось — стандартный персонаж."""
    path = Path(settings.sprite_path) if settings.sprite_path else None
    try:
        if settings.sprite_source == "folder" and path and path.is_dir():
            return SpriteSheet.from_folder(path)
        if settings.sprite_source == "file" and path and path.is_file():
            img = Image.open(path).convert("RGBA")
            return SpriteSheet.from_sheet(img, settings.sprite_cell_w, settings.sprite_cell_h, auto_box=True)
    except (OSError, ValueError) as exc:
        if log:
            log.error(f"Не удалось загрузить скин: {exc}. Использую стандартный персонаж.")
    return default_sprite_sheet()


def export_sprite_preview(path: Path, sheet: SpriteSheet) -> Path:
    """Картинка со всеми рядами и их номерами — чтобы выбрать ряды для анимаций."""
    per_line, label_w = 24, 70
    cw, ch = sheet.cell_w, sheet.cell_h
    lines: list[tuple[Any, list[Image.Image]]] = []
    for key in sorted(sheet.rows, key=lambda k: (0, k) if isinstance(k, int) else (1, str(k))):
        cells = sheet.rows[key]
        for i in range(0, len(cells), per_line):
            lines.append((key if i == 0 else None, cells[i:i + per_line]))
    out = Image.new("RGB", (label_w + per_line * cw, len(lines) * ch + 8), (45, 45, 55))
    draw = ImageDraw.Draw(out)
    y = 0
    for label, chunk in lines:
        if label is not None:
            text = f"R{label}" if isinstance(label, int) else str(label)[:10]
            draw.text((6, y + ch // 2 - 6), text, fill=(255, 230, 80))
        for j, cell in enumerate(chunk):
            bg = Image.new("RGBA", (cw, ch), (45, 45, 55, 255))
            bg.alpha_composite(cell)
            out.paste(bg.convert("RGB"), (label_w + j * cw, y))
        y += ch
    out.save(path)
    return path


class AvatarWindow(Presenter):
    """
    Персонаж в правом нижнем углу рабочего стола. Окно без рамки, прозрачный фон,
    поверх всех окон. Над персонажем — пузырь с ответом. Перетаскивается мышью.
    Все вызовы set_state/say потокобезопасны: команды кладутся в очередь и применяются
    в главном потоке Tk.
    """

    KEY = "#ff00fe"           # цвет, который Windows делает прозрачным
    BUBBLE_W = 340
    BUBBLE_MAX_H = 260
    PAD = 12
    TAIL = 14
    FONT = ("Segoe UI", 11)

    def __init__(self, settings: Settings, log: Logger, quit_evt: threading.Event):
        self.log = log
        self.settings = settings
        self._quit = quit_evt
        self._cmds: queue.Queue = queue.Queue()
        self._anim_after: Optional[str] = None
        self._bubble_after: Optional[str] = None
        self._state = "idle"
        self._frames: list = []
        self._idx = 0
        self._loop = True
        self._delay = 300

        self.root = tk.Tk()
        self.root.withdraw()
        self.root.title("PCFER")
        self.root.overrideredirect(True)
        self.root.attributes("-topmost", True)
        self.root.attributes("-transparentcolor", self.KEY)
        self.root.configure(bg=self.KEY)

        self.sheet = load_sprite_sheet(settings, log)
        self.scale = clamp_scale(settings.avatar_scale)
        self.canvas = tk.Canvas(self.root, width=self.BUBBLE_W, height=self.BUBBLE_MAX_H,
                                bg=self.KEY, highlightthickness=0, bd=0)
        self.canvas.pack()
        self.photos: dict[str, list] = {}
        self._build_photos()
        self.sprite = self.canvas.create_image(0, 0, anchor="nw", image=self.photos["idle"][0])
        self.canvas.bind("<ButtonPress-1>", self._drag_start)
        self.canvas.bind("<B1-Motion>", self._drag_move)
        self._layout()

        self._play_event("startup")  # по умолчанию машет рукой, назначение меняется в панели
        self._refresh()
        self.root.after(30, self._pump)
        self._schedule_filler()

    def _schedule_filler(self) -> None:
        """Через случайную паузу простоя показывает короткий жест (осмотреться, моргнуть и т.п.)."""
        base = max(5.0, float(self.settings.idle_delay_s))
        self.root.after(int(random.uniform(0.6, 1.4) * base * 1000), self._play_filler)

    def _play_filler(self) -> None:
        if self.settings.idle_fillers_enabled and self._state == "idle" and not self._quit.is_set():
            self._apply_state(random.choice(IDLE_FILLERS))
        self._schedule_filler()

    # ── размер персонажа ─────────────────────────────────────────────────────
    def set_scale(self, scale: int) -> None:
        self._cmds.put(("scale", clamp_scale(scale)))

    def event(self, name: str) -> None:
        self._cmds.put(("event", name))

    def preview(self, name: str) -> None:
        self._cmds.put(("anim", name))

    def refresh(self) -> None:
        self._cmds.put(("refresh", None))

    def _play_event(self, name: str) -> None:
        """Проигрывает анимацию, назначенную событию в настройках ("idle" — просто ожидание)."""
        if name == "idle":
            self._apply_state("idle")
            return
        anim = self.settings.anim_events.get(name, "")
        self._apply_state(anim if anim in self.settings.avatar_states else "idle")

    def _refresh(self) -> None:
        """Применяет из настроек видимость, размер, угол, прозрачность и поверх окон."""
        s = self.settings
        self._set_visible_now(s.avatar_enabled)
        self.sheet = load_sprite_sheet(s, self.log)
        self.scale = clamp_scale(s.avatar_scale)
        self._rebuild()
        self.root.attributes("-topmost", bool(s.avatar_topmost))
        self.root.attributes("-alpha", max(0.3, min(1.0, float(s.avatar_alpha))))
        self._place()

    def _build_photos(self) -> None:
        """Готовит кадры всех состояний в текущем масштабе. Состояния и ряды берутся из настроек."""
        self.photos = {}
        cache: dict[tuple, list] = {}
        for name, cfg in self.settings.avatar_states.items():
            rows = list(cfg.get("rows", []))
            key = tuple(str(r) for r in rows)
            if key not in cache:
                cells = self.sheet.frames(rows) or self.sheet.fallback()
                cache[key] = [ImageTk.PhotoImage(SpriteSheet.render(c, self.sheet.box, self.scale), master=self.root)
                              for c in cells]
            self.photos[name] = cache[key]
        if "idle" not in self.photos:
            cell = self.sheet.fallback()[0]
            self.photos["idle"] = [ImageTk.PhotoImage(SpriteSheet.render(cell, self.sheet.box, self.scale), master=self.root)]

    def _rebuild(self) -> None:
        """Перерисовывает персонажа после смены размера, скина или списка анимаций."""
        self._build_photos()
        self._layout()
        self.canvas.delete("bubble")
        self._apply_state(self._state)

    def _layout(self) -> None:
        """Пересчитывает размеры окна и положение персонажа по текущим кадрам."""
        self.sprite_w = self.photos["idle"][0].width()
        self.sprite_h = self.photos["idle"][0].height()
        self.canvas_w = max(self.BUBBLE_W, self.sprite_w)
        self.canvas_h = self.BUBBLE_MAX_H + self.TAIL + self.sprite_h + 8
        self.canvas.configure(width=self.canvas_w, height=self.canvas_h)
        self.canvas.coords(self.sprite, (self.canvas_w - self.sprite_w) // 2, self.canvas_h - self.sprite_h)
        self._place()

    def _change_scale(self, scale: int) -> None:
        if scale == self.scale:
            return
        self.scale = scale
        self._build_photos()
        self._layout()
        self.canvas.delete("bubble")
        self._apply_state(self._state)

    # ── потокобезопасный интерфейс ───────────────────────────────────────────
    def set_state(self, name: str) -> None:
        self._cmds.put(("state", name))

    def say(self, text: str) -> None:
        self._cmds.put(("say", clean_text(text, 300)))

    def set_visible(self, visible: bool) -> None:
        self._cmds.put(("visible", visible))

    def run(self, quit_evt: threading.Event) -> None:
        self.root.mainloop()
        try:
            self.root.destroy()
        except tk.TclError:
            pass

    # ── главный цикл Tk ──────────────────────────────────────────────────────
    def _pump(self) -> None:
        try:
            while True:
                cmd, *args = self._cmds.get_nowait()
                if cmd == "state":
                    self._apply_state(args[0])
                elif cmd == "say":
                    self._show_bubble(args[0])
                elif cmd == "visible":
                    self._set_visible_now(args[0])
                elif cmd == "scale":
                    self._change_scale(args[0])
                elif cmd == "event":
                    self._play_event(args[0])
                elif cmd == "anim":
                    if args[0] in self.settings.avatar_states:
                        self._apply_state(args[0])
                elif cmd == "refresh":
                    self._refresh()
        except queue.Empty:
            pass
        if self._quit.is_set():
            self.root.quit()
            return
        self.root.after(30, self._pump)

    # ── анимация ─────────────────────────────────────────────────────────────
    def _apply_state(self, name: str) -> None:
        if name not in self.photos:
            name = "idle"
        cfg = self.settings.avatar_states.get(name, {"loop": True, "fps": 3.0})
        if self._anim_after:
            self.root.after_cancel(self._anim_after)
        self._state = name
        self._frames = self.photos[name]
        self._loop = cfg["loop"]
        self._delay = max(1, int(1000 / cfg["fps"]))
        self._idx = 0
        self.canvas.itemconfigure(self.sprite, image=self._frames[0])
        self._anim_after = self.root.after(self._delay, self._advance)

    def _advance(self) -> None:
        self._idx += 1
        if self._idx >= len(self._frames):
            if self._loop:
                self._idx = 0
            else:
                self._apply_state("idle")
                return
        self.canvas.itemconfigure(self.sprite, image=self._frames[self._idx])
        self._anim_after = self.root.after(self._delay, self._advance)

    # ── пузырь с ответом ─────────────────────────────────────────────────────
    def _show_bubble(self, text: str) -> None:
        if not self.settings.bubble_enabled:
            text = ""
        self.canvas.delete("bubble")
        if self._bubble_after:
            self.root.after_cancel(self._bubble_after)
            self._bubble_after = None
        if not text:
            return
        base = self.canvas_h - self.sprite_h - 4 - self.TAIL   # низ пузыря
        tip = base + self.TAIL                                # кончик хвоста над головой
        wrap = self.BUBBLE_W - 2 * self.PAD
        probe = self.canvas.create_text(0, 0, text=text, anchor="nw", width=wrap, font=self.FONT)
        x0, y0, x1, y1 = self.canvas.bbox(probe)
        self.canvas.delete(probe)
        h = (y1 - y0) + 2 * self.PAD
        top = max(0, base - h)
        left, right = (self.canvas_w - self.BUBBLE_W) // 2, (self.canvas_w + self.BUBBLE_W) // 2
        cx = self.canvas_w // 2
        self.canvas.create_polygon(cx - 9, base - 1, cx + 9, base - 1, cx, tip,
                                   fill="#ffffff", outline="#3a3a3a", width=2, tags="bubble")
        self._rounded_rect(left, top, right, base, 14, "bubble")
        self.canvas.create_text(left + self.PAD, top + self.PAD, text=text, anchor="nw",
                                width=wrap, font=self.FONT, fill="#1c1c1c", tags="bubble")
        seconds = self.settings.bubble_seconds or min(20.0, max(4.0, len(text) / 10 + 2))
        self._bubble_after = self.root.after(int(seconds * 1000), lambda: self.canvas.delete("bubble"))

    def _rounded_rect(self, x0, y0, x1, y1, r, tag) -> None:
        pts = [x0 + r, y0, x1 - r, y0, x1, y0, x1, y0 + r, x1, y1 - r, x1, y1,
               x1 - r, y1, x0 + r, y1, x0, y1, x0, y1 - r, x0, y0 + r, x0, y0]
        self.canvas.create_polygon(pts, smooth=True, fill="#ffffff", outline="#3a3a3a", width=2, tags=tag)

    # ── положение и перетаскивание ──────────────────────────────────────────
    def _place(self) -> None:
        left, top, right, bottom = work_area()
        corner = self.settings.avatar_corner
        x = right - self.canvas_w - 6 if "right" in corner else left + 6
        y = bottom - self.canvas_h if "bottom" in corner else top + 6
        self.root.geometry(f"{self.canvas_w}x{self.canvas_h}+{x}+{y}")

    def _drag_start(self, e) -> None:
        self._dx = e.x_root - self.root.winfo_x()
        self._dy = e.y_root - self.root.winfo_y()

    def _drag_move(self, e) -> None:
        self.root.geometry(f"+{e.x_root - self._dx}+{e.y_root - self._dy}")

    def _set_visible_now(self, visible: bool) -> None:
        if visible:
            self.root.deiconify()
        else:
            self.root.withdraw()


# ══════════════════════════════════════════════════════════════════════════════
#  Действия
# ══════════════════════════════════════════════════════════════════════════════
class Action(ABC):
    name: str = ""              # идентификатор для LLM и настроек
    title: str = ""             # подпись переключателя в панели
    description: str = ""       # что делает (для LLM)
    args_help: str = "{}"       # формат аргументов (для LLM)
    speak_result: bool = False  # озвучивать ли результат run()

    def __init__(self, ctx: Context):
        self.ctx = ctx

    @abstractmethod
    def run(self, **args: Any) -> str: ...

    def prompt_line(self) -> str:
        return f'- "{self.name}": {self.description} args: {self.args_help}'


class ScreenshotAction(Action):
    name = "screenshot"
    title = "Скриншот"
    description = "сделать снимок экрана и сохранить в файл."

    def run(self, **args):
        path = self.ctx.screen.save_screenshot()
        self.ctx.log.ok(f"Скриншот: {path}")
        return f"Скриншот сохранён: {path.name}"


class ScreenRecordAction(Action):
    name = "screen_record"
    title = "Запись видео экрана"
    description = "начать или остановить запись видео с экрана."
    args_help = '{"state": "start" | "stop"}'

    def run(self, **args):
        if str(args.get("state", "start")).lower() == "stop":
            path = self.ctx.recorder.stop()
            self.ctx.log.ok(f"Видео сохранено: {path}")
            return f"Запись остановлена, файл {path.name}"
        path = self.ctx.recorder.start()
        self.ctx.log.ok(f"Запись идёт: {path}")
        return "Запись экрана началась"


class OpenWebsiteAction(Action):
    name = "open_website"
    title = "Открытие сайтов"
    description = "открыть сайт в браузере или найти что-то в интернете."
    args_help = '{"url": "адрес или название сайта", "query": "поисковый запрос, если нужен поиск"}'

    ALIASES = {
        "youtube": "https://youtube.com", "ютуб": "https://youtube.com",
        "google": "https://google.com", "гугл": "https://google.com",
        "github": "https://github.com", "гитхаб": "https://github.com",
        "яндекс": "https://yandex.ru", "yandex": "https://yandex.ru",
        "вк": "https://vk.com", "vk": "https://vk.com",
        "википедия": "https://ru.wikipedia.org", "wikipedia": "https://wikipedia.org",
    }

    def run(self, **args):
        target = str(args.get("url") or "").strip()
        query = str(args.get("query") or "").strip()
        if not target and query:
            target = "https://www.google.com/search?q=" + quote_plus(query)
        elif target.lower() in self.ALIASES:
            target = self.ALIASES[target.lower()]
        elif target and not re.match(r"^\w+://", target):
            if "." in target and " " not in target:
                target = "https://" + target
            else:
                target = "https://www.google.com/search?q=" + quote_plus(target)
        if not target:
            raise ValueError("Не указан сайт")
        webbrowser.open(target)
        self.ctx.log.ok(f"Открыто: {target}")
        return "Открываю"


class OpenAppAction(Action):
    name = "open_app"
    title = "Запуск приложений"
    description = "запустить программу по названию: сначала ищет в индексе программ на дисках, потом в меню «Пуск»."
    args_help = '{"name": "название приложения"}'

    # системные программы Windows, которых нет в индексе как файлов
    SYSTEM = {
        "блокнот": "notepad", "notepad": "notepad", "калькулятор": "calc", "calculator": "calc",
        "проводник": "explorer", "paint": "mspaint", "пэйнт": "mspaint",
        "диспетчер задач": "taskmgr", "командная строка": "cmd", "cmd": "cmd",
        "терминал": "wt", "настройки": "ms-settings:", "параметры": "ms-settings:",
    }

    def run(self, **args):
        name = str(args.get("name") or "").strip()
        if not name:
            raise ValueError("Не указано приложение")
        if name.lower() in self.SYSTEM:
            subprocess.Popen(["cmd", "/c", "start", "", self.SYSTEM[name.lower()]], creationflags=NO_WINDOW)
            self.ctx.log.ok(f"Запущено: {name}")
            return f"Открываю {name}"
        entry = self.ctx.apps.find(name)
        if entry:
            AppLauncher.open(entry.path)
            self.ctx.log.ok(f"Запущено: {entry.name} ({entry.path})")
            return f"Открываю {entry.name}"
        inp = self.ctx.input  # последний вариант: поиск через меню «Пуск»
        inp.press("win")
        time.sleep(0.7)
        inp.type_text(name)
        time.sleep(1.0)
        inp.press("enter")
        self.ctx.log.warning(f"«{name}» нет в индексе, ищу через меню «Пуск».")
        return f"Ищу {name}"


class OpenPathAction(Action):
    name = "open_path"
    title = "Открытие папок и файлов"
    description = "открыть папку или файл по полному пути (например D:\\Игры)."
    args_help = '{"path": "полный путь к папке или файлу"}'

    def run(self, **args):
        path = str(args.get("path") or "").strip().strip('"')
        if not path or not os.path.exists(path):
            raise ValueError(f"Путь не найден: {path or '(пусто)'}")
        AppLauncher.open(path)
        self.ctx.log.ok(f"Открыто: {path}")
        return f"Открываю {Path(path).name or path}"


class ListDrivesAction(Action):
    name = "list_drives"
    title = "Диски и программы"
    description = "назвать диски компьютера, сколько на них свободного места и сколько программ найдено."
    args_help = "{}"
    speak_result = True

    def run(self, **args):
        lines = DriveScanner.lines()
        if not lines:
            return "Диски не найдены."
        for line in lines:
            self.ctx.log.info(line)
        return f"Дисков: {len(lines)}. " + "; ".join(lines) + f". Программ в индексе: {self.ctx.apps.count}."


class MouseAction(Action):
    name = "mouse"
    title = "Управление мышью"
    description = "двигать мышь, кликать по координатам, прокручивать."
    args_help = ('{"op": "click"|"double_click"|"right_click"|"move"|"scroll", "x": px, "y": px, '
                 '"amount": число (вверх > 0, вниз < 0, по умолчанию -500)}')

    def run(self, **args):
        inp = self.ctx.input
        op = str(args.get("op", "click")).lower()
        x = int(args["x"]) if args.get("x") is not None else None
        y = int(args["y"]) if args.get("y") is not None else None
        if op == "move":
            if x is None or y is None:
                raise ValueError("Для перемещения нужны x и y")
            inp.move(x, y)
        elif op == "scroll":
            inp.scroll(int(args.get("amount", -500)))
        elif op in ("click", "double_click", "right_click"):
            inp.click(x, y, "right" if op == "right_click" else "left", 2 if op == "double_click" else 1)
        else:
            raise ValueError(f"Неизвестная операция мыши: {op}")
        return "Готово"


class KeyboardAction(Action):
    name = "keyboard"
    title = "Управление клавиатурой"
    description = "напечатать текст, нажать клавишу или сочетание клавиш."
    args_help = '{"text": "что напечатать", "hotkey": ["ctrl","c"], "key": "enter"} (любые поля по необходимости)'

    def run(self, **args):
        inp, done = self.ctx.input, False
        if args.get("text"):
            inp.type_text(str(args["text"]))
            done = True
        if args.get("hotkey"):
            keys = args["hotkey"]
            if isinstance(keys, str):
                keys = [k for k in re.split(r"[+\s,]+", keys) if k]
            inp.hotkey(*keys)
            done = True
        if args.get("key"):
            inp.press(str(args["key"]))
            done = True
        if not done:
            raise ValueError("Не указано, что напечатать или нажать")
        return "Готово"


class LookAtScreenAction(Action):
    name = "look_at_screen"
    title = "Зрение (видит экран)"
    description = "посмотреть на экран и ответить, что на нём происходит или что там написано."
    args_help = '{"question": "что нужно узнать про экран"}'
    speak_result = True

    def run(self, **args):
        question = str(args.get("question") or "Кратко опиши, что сейчас на экране.")
        return self.ctx.vision(f"{question}\nОтвечай по-русски, кратко, 1–3 предложения, без markdown.").strip()


class ClickOnScreenAction(Action):
    name = "click_on_screen"
    title = "Клик по элементу на экране"
    description = "найти на экране элемент (кнопку, иконку, ссылку) по описанию и кликнуть по нему."
    args_help = '{"target": "описание элемента", "button": "left"|"right", "double": true|false}'

    def run(self, **args):
        target = str(args.get("target") or "").strip()
        if not target:
            raise ValueError("Не указан элемент для клика")
        prompt = (
            f'На изображении экран компьютера. Найди элемент: "{target}". '
            'Верни ТОЛЬКО JSON {"found": true|false, "x": число от 0 до 1, "y": число от 0 до 1}, '
            "где x, y — относительные координаты центра элемента (0,0 — левый верхний угол)."
        )
        data = extract_json(self.ctx.vision(prompt, json_mode=True)) or {}
        if not data.get("found") or data.get("x") is None or data.get("y") is None:
            return f"Не нашёл на экране: {target}"
        w, h = self.ctx.input.screen_size()
        px, py = int(float(data["x"]) * w), int(float(data["y"]) * h)
        self.ctx.log.info(f"Клик по «{target}»: ({px}, {py})")
        self.ctx.input.click(px, py, "right" if args.get("button") == "right" else "left",
                             2 if args.get("double") else 1)
        return "Кликнул"


ACTION_CLASSES: list[type[Action]] = [
    ScreenshotAction, ScreenRecordAction, OpenWebsiteAction, OpenAppAction, OpenPathAction,
    ListDrivesAction, KeyboardAction, MouseAction, LookAtScreenAction, ClickOnScreenAction,
]


# ══════════════════════════════════════════════════════════════════════════════
#  Мозг: решает, отвечать или выполнять действие
# ══════════════════════════════════════════════════════════════════════════════
@dataclass
class Decision:
    action: str = "none"
    args: dict = field(default_factory=dict)
    reply: str = ""


class Brain:
    HISTORY_LIMIT = 12

    def __init__(self, settings: Settings, actions: dict[str, Action]):
        self.settings = settings
        self.actions = actions
        self.history: list[dict] = []

    def system_prompt(self) -> str:
        enabled = [a for a in self.actions.values() if self.settings.actions.get(a.name, True)]
        lines = "\n".join(a.prompt_line() for a in enabled) or "(все действия отключены)"
        return (
            f"Ты — {self.settings.assistant_name}, голосовой ассистент на компьютере пользователя. "
            "Твой ответ озвучивается, поэтому говори коротко (1–3 предложения), без markdown и списков.\n"
            f"Сейчас: {datetime.now():%d.%m.%Y %H:%M}. Язык общения: {self.settings.language}.\n\n"
            'Верни ТОЛЬКО JSON: {"action": "<имя действия или none>", "args": {...}, "reply": "<что сказать>"}\n\n'
            "Правила:\n"
            "1. Выбирай действие ТОЛЬКО если пользователь явно попросил его в этой реплике. "
            "Ничего не делай по своей инициативе и не додумывай лишнего.\n"
            '2. Вопрос или разговор — action "none", а в reply полный ответ.\n'
            "3. Если выбрано действие — в reply короткая фраза-подтверждение («Открываю YouTube»).\n"
            "4. Одно действие за раз.\n"
            "5. Для программ используй open_app с названием, как его говорит пользователь.\n"
            "6. Доступны ТОЛЬКО эти действия:\n" + lines
            + (f"\n\nДополнительно: {self.settings.persona_extra}" if self.settings.persona_extra.strip() else "")
        )

    def clear_history(self) -> None:
        self.history = []

    def decide(self, user_text: str) -> Decision:
        messages = [{"role": "system", "content": self.system_prompt()}, *self.history,
                    {"role": "user", "content": user_text}]
        raw = make_provider(self.settings).chat(messages, json_mode=True)
        data = extract_json(raw)
        if data and "action" in data:
            args = data.get("args")
            decision = Decision(str(data.get("action") or "none").strip(),
                                args if isinstance(args, dict) else {},
                                str(data.get("reply") or "").strip())
        else:  # модель не вернула JSON — считаем ответ обычным текстом
            decision = Decision(reply=(raw or "").strip())
        self.history += [{"role": "user", "content": user_text},
                         {"role": "assistant", "content": decision.reply or decision.action}]
        limit = self.settings.history_len
        self.history = self.history[-limit:] if limit > 0 else []
        return decision


# ══════════════════════════════════════════════════════════════════════════════
#  Ассистент (оркестратор): цикл прослушивания и обработка запросов
# ══════════════════════════════════════════════════════════════════════════════
class Assistant:
    def __init__(self, settings: Settings, log: Logger, presenter: Optional[Presenter] = None):
        self.settings = settings
        self.log = log
        self.presenter = presenter or Presenter()
        self.ctx = Context(settings, log)
        self.actions = {cls.name: cls(self.ctx) for cls in ACTION_CLASSES}
        self.brain = Brain(settings, self.actions)
        self.speech = SpeechService(settings, log)
        self.listener = VoiceListener(settings, log)
        self.trigger = TriggerDetector(settings)
        self._stop = threading.Event()
        self._thread: Optional[threading.Thread] = None
        self._busy = threading.Lock()

    @property
    def running(self) -> bool:
        return self._thread is not None and self._thread.is_alive()

    def start(self) -> None:
        if self.running and not self._stop.is_set():
            return
        if self.running:  # ещё не успел завершиться после stop() — дождёмся
            self._thread.join(timeout=20)
            if self.running:
                return
        self._stop.clear()
        self._thread = threading.Thread(target=self._loop, daemon=True, name="pcfer-loop")
        self._thread.start()

    def stop(self) -> None:
        self._stop.set()
        if self.ctx.recorder.recording:
            try:
                self.ctx.recorder.stop()
            except Exception:
                pass

    def rescan_if_needed(self) -> None:
        if self.ctx.apps.is_stale():
            self.ctx.apps.scan_async(self.log)

    def _loop(self) -> None:
        """Главный цикл: триггер → запрос → ответ/действие."""
        try:
            self.listener.open()
            self.log.ok(f"Слушаю. Скажите «{self.settings.trigger}», а затем запрос.")
            while not self._stop.is_set():
                self.log.state(f"Жду триггер «{self.settings.trigger}»")
                heard = self.listener.listen(timeout=3, phrase_limit=8)
                if not heard:
                    continue
                self.log.info(f"Слышу: {heard}")
                query = self.trigger.find(heard)
                if query is None:
                    continue
                if not query:
                    self.presenter.event("listen")
                    self._maybe_speak("Слушаю")
                    self.log.state("Слушаю запрос…")
                    query = self.listener.listen(timeout=self.settings.follow_up_timeout, phrase_limit=15)
                    if not query:
                        self.log.warning("Запрос не расслышан")
                        self._say("Не расслышал")
                        continue
                self.handle(query)
        except Exception:
            self.log.exception("Ошибка в цикле ассистента")
        finally:
            self.listener.close()
            self.presenter.set_state("idle")
            self.log.state("Остановлен")

    def submit_text(self, text: str) -> None:
        """Текстовая команда (из панели), без микрофона."""
        threading.Thread(target=self.handle, args=(text,), daemon=True).start()

    def handle(self, text: str) -> None:
        with self._busy:
            self.log.user(text)
            self.presenter.event("think")
            try:
                custom = self._match_custom(text)
                if custom:
                    self._run_custom(custom)
                else:
                    self._execute(self.brain.decide(text))
            except Exception as exc:
                self.log.exception("Ошибка при обработке запроса")
                self._say(f"Произошла ошибка: {exc}", mood="error")
            finally:
                self.log.state(f"Жду триггер «{self.settings.trigger}»" if self.running else "Остановлен")

    ARG_KEYS = {"open_website": "url", "open_app": "name", "open_path": "path", "keyboard": "text"}

    def _match_custom(self, text: str) -> Optional[dict]:
        """Ищет свою команду по фразе — такие команды выполняются без обращения к модели."""
        low = text.lower()
        for item in self.settings.custom_commands:
            phrase = str(item.get("phrase", "")).strip().lower()
            if phrase and phrase in low:
                return item
        return None

    def _run_custom(self, item: dict) -> None:
        kind = str(item.get("action", "say"))
        arg = str(item.get("arg", ""))
        self.log.info(f"Своя команда «{item.get('phrase')}» → {kind}")
        if kind == "say":
            self._say(arg or "Готово")
            return
        action = self.actions.get(kind)
        if action is None or not self.settings.actions.get(kind, True):
            self._say(f"Действие «{kind}» недоступно.", mood="error")
            return
        self.presenter.event("think")
        try:
            result = action.run(**{self.ARG_KEYS.get(kind, "text"): arg})
        except Exception as exc:
            self.log.exception("Своя команда завершилась ошибкой")
            self._say(f"Не получилось: {exc}", mood="error")
            return
        if result:
            self._say(result, mood="success")
        else:
            self.presenter.event("success")

    def _say(self, text: str, mood: str = "idle") -> None:
        """Говорит и показывает пузырь. mood — событие для персонажа после ответа."""
        self.log.bot(text)
        self.presenter.say(text)
        self.presenter.event("talk")
        try:
            self._maybe_speak(text)
        finally:
            self.presenter.event(mood)

    def _maybe_speak(self, text: str) -> None:
        """Озвучивает, если озвучка включена и сейчас не тихие часы."""
        if self.settings.speak_replies and not self.settings.quiet_now():
            self.speech.speak(text)

    def _execute(self, d: Decision) -> None:
        if d.action in ("", "none", "null", "chat"):
            self._say(d.reply or "Не знаю, что ответить.")
            return
        action = self.actions.get(d.action)
        if action is None:
            self.log.warning(f"Модель запросила неизвестное действие: {d.action}")
            self._say(d.reply or "Не понял, что нужно сделать.", mood="error")
            return
        if not self.settings.actions.get(action.name, True):
            self._say(f"Действие «{action.title}» отключено в панели управления.")
            return
        if d.reply:
            self._say(d.reply)
        self.presenter.event("think")
        self.log.state(f"Выполняю: {action.title}")
        self.log.info(f"Действие {action.name} {json.dumps(d.args, ensure_ascii=False)}")
        try:
            result = action.run(**d.args)
        except Exception as exc:
            self.log.exception(f"Действие «{action.title}» завершилось ошибкой")
            self._say(f"Не получилось: {exc}", mood="error")
            return
        if action.speak_result and result:
            self._say(result, mood="success")
            return
        if result:
            self.log.info(result)
            self.presenter.say(result)
        magic = action.name in ("screenshot", "screen_record")
        self.presenter.event("magic" if magic else "success")


# ══════════════════════════════════════════════════════════════════════════════
#  IPC: связь панели с сервисом через localhost (одна JSON-строка на запрос и ответ)
# ══════════════════════════════════════════════════════════════════════════════
def _read_line(sock: socket.socket) -> str:
    buf = b""
    while not buf.endswith(b"\n"):
        chunk = sock.recv(4096)
        if not chunk:
            break
        buf += chunk
    return buf.decode("utf-8").strip()


def ipc(cmd: str, **data: Any) -> Optional[dict]:
    """Отправляет команду сервису. None — сервис не отвечает (не запущен)."""
    try:
        with socket.create_connection(("127.0.0.1", IPC_PORT), timeout=3) as sock:
            sock.sendall((json.dumps({"cmd": cmd, **data}, ensure_ascii=False) + "\n").encode("utf-8"))
            reply = _read_line(sock)
            return json.loads(reply) if reply else None
    except (OSError, ValueError):
        return None


def make_presenter(settings: Settings, log: Logger, quit_evt: threading.Event) -> Presenter:
    """Пытается показать персонажа; если tkinter/спрайты недоступны — сервис работает без него."""
    try:
        return AvatarWindow(settings, log, quit_evt)
    except Exception:
        log.exception("Персонаж не запущен, сервис работает без него")
        return Presenter()


OLLAMA_URL = "http://127.0.0.1:11434"
OLLAMA_DIR = APP_DIR / "ollama"   # рядом с программой: ollama.exe и папка models


def ollama_alive() -> bool:
    """Отвечает ли сервер Ollama на порту 11434."""
    try:
        with urllib.request.urlopen(OLLAMA_URL, timeout=1.5) as resp:
            return resp.status == 200
    except OSError:
        return False


def ensure_ollama(log: Optional[Logger] = None) -> bool:
    """
    Если Ollama уже работает (своя установка) — ничего не делает.
    Иначе запускает ollama.exe из папки PCFER/ollama, а модели берёт из PCFER/ollama/models.
    """
    if ollama_alive():
        return True
    exe = OLLAMA_DIR / "ollama.exe"
    if not exe.exists():
        if log:
            log.warning("Ollama не запущена и не найдена в папке PCFER\\ollama. Установите Ollama или проверьте папку.")
        return False
    env = os.environ.copy()
    env["OLLAMA_MODELS"] = str(OLLAMA_DIR / "models")
    subprocess.Popen(
        [str(exe), "serve"],
        cwd=str(OLLAMA_DIR),
        env=env,
        creationflags=subprocess.DETACHED_PROCESS | subprocess.CREATE_NEW_PROCESS_GROUP | NO_WINDOW,
        close_fds=True,
    )
    for _ in range(40):  # до ~20 секунд ждём запуска сервера
        time.sleep(0.5)
        if ollama_alive():
            if log:
                log.ok("Ollama запущена из папки PCFER.")
            return True
    if log:
        log.error("Ollama из папки PCFER не ответила после запуска.")
    return False


class Daemon:
    """Фоновый сервис: держит Assistant и персонажа, принимает команды панели."""

    def __init__(self, settings: Settings, log: Logger):
        self.settings = settings
        self.log = log
        self._quit = threading.Event()
        self.presenter = make_presenter(settings, log, self._quit)
        self.assistant = Assistant(settings, log, presenter=self.presenter)

    def run(self) -> None:
        srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            srv.bind(("127.0.0.1", IPC_PORT))
        except OSError:
            self.log.info("PCFER-сервис уже работает, второй экземпляр не запускаю.")
            srv.close()
            return
        srv.listen(8)
        srv.settimeout(1.0)
        threading.Thread(target=ensure_ollama, args=(self.log,), daemon=True).start()
        threading.Thread(target=self._accept_loop, args=(srv,), daemon=True).start()
        if self.settings.autostart_listen:
            self.assistant.start()
        self.assistant.rescan_if_needed()
        self.log.ok("PCFER-сервис запущен.")
        try:
            self.presenter.run(self._quit)  # главный поток: окно персонажа (или ожидание)
        except Exception:
            self.log.exception("Окно персонажа остановилось, сервис продолжает работать")
            self._quit.wait()
        finally:
            self._quit.set()
            self.assistant.stop()
            srv.close()
            self.log.info("PCFER-сервис остановлен.")

    def _accept_loop(self, srv: socket.socket) -> None:
        while not self._quit.is_set():
            try:
                conn, _ = srv.accept()
            except socket.timeout:
                continue
            except OSError:
                break
            threading.Thread(target=self._serve, args=(conn,), daemon=True).start()

    def _serve(self, conn: socket.socket) -> None:
        with conn:
            conn.settimeout(5)
            try:
                req = json.loads(_read_line(conn) or "{}")
                resp = self._dispatch(req)
            except Exception as exc:
                self.log.exception("Ошибка команды сервиса")
                resp = {"ok": False, "error": str(exc)}
            conn.sendall((json.dumps(resp, ensure_ascii=False) + "\n").encode("utf-8"))

    def _dispatch(self, req: dict) -> dict:
        cmd = req.get("cmd")
        if cmd == "status":
            return {"ok": True, "running": self.assistant.running, "state": self.log.last_state,
                    "apps": self.assistant.ctx.apps.count, "scanning": self.assistant.ctx.apps.scanning}
        if cmd == "start":
            self.assistant.start()
            return {"ok": True}
        if cmd == "stop":
            self.assistant.stop()
            return {"ok": True}
        if cmd == "reload":  # настройки из файла применяются без перезапуска
            self.settings.update_from(Settings.load())
            self.presenter.refresh()
            self.log.info("Настройки применены.")
            return {"ok": True}
        if cmd == "text":
            self.assistant.submit_text(str(req.get("text", "")))
            return {"ok": True}
        if cmd == "rescan":
            self.assistant.ctx.apps.scan_async(self.log)
            return {"ok": True}
        if cmd == "drives":
            for line in DriveScanner.lines():
                self.log.info(line)
            return {"ok": True}
        if cmd == "sprites":
            path = export_sprite_preview(APP_DIR / "pcfer_sprites_preview.png",
                                         load_sprite_sheet(self.settings, self.log))
            os.startfile(path)  # type: ignore[attr-defined]
            return {"ok": True}
        if cmd == "anim":
            self.presenter.preview(str(req.get("name", "")))
            return {"ok": True}
        if cmd == "clear_history":
            self.assistant.brain.clear_history()
            return {"ok": True}
        if cmd == "shutdown":
            self._quit.set()
            return {"ok": True}
        return {"ok": False, "error": f"неизвестная команда: {cmd}"}


# ══════════════════════════════════════════════════════════════════════════════
#  Ярлыки и автозапуск (через PowerShell / WScript.Shell, без дополнительных библиотек)
# ══════════════════════════════════════════════════════════════════════════════
def pythonw() -> str:
    """Программа для запуска без окна: сам exe либо pythonw из того же venv."""
    if FROZEN:
        return str(SCRIPT)
    exe = Path(sys.executable)
    candidate = exe.with_name("pythonw.exe")
    return str(candidate if candidate.exists() else exe)


def _launch_args(flag: str) -> str:
    """Аргументы для ярлыка и автозапуска: в exe скрипт не передаётся."""
    return flag if FROZEN else f'"{SCRIPT}" {flag}'


def _ps_quote(text: str) -> str:
    return "'" + text.replace("'", "''") + "'"


def _powershell(script: str) -> subprocess.CompletedProcess:
    return subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", script],
                          capture_output=True, text=True, creationflags=NO_WINDOW)


def _special_folder(name: str) -> Path:
    result = _powershell(f"[Environment]::GetFolderPath('{name}')")
    return Path(result.stdout.strip())


def _make_shortcut(path: Path, args: str, description: str) -> None:
    script = (
        f"$s = (New-Object -ComObject WScript.Shell).CreateShortcut({_ps_quote(str(path))});"
        f"$s.TargetPath = {_ps_quote(pythonw())};"
        f"$s.Arguments = {_ps_quote(args)};"
        f"$s.WorkingDirectory = {_ps_quote(str(APP_DIR))};"
        f"$s.Description = {_ps_quote(description)};"
        "$s.Save()"
    )
    result = _powershell(script)
    if result.returncode != 0:
        raise RuntimeError(f"Не удалось создать ярлык {path.name}: {result.stderr.strip()}")


def start_service() -> None:
    """Запускает фоновый сервис отдельным процессом, без окна и без привязки к панели."""
    cmd = [pythonw(), "--background"] if FROZEN else [pythonw(), str(SCRIPT), "--background"]
    subprocess.Popen(
        cmd,
        cwd=str(APP_DIR),
        creationflags=subprocess.DETACHED_PROCESS | subprocess.CREATE_NEW_PROCESS_GROUP | NO_WINDOW,
        close_fds=True,
    )


def install() -> None:
    desktop = _special_folder("Desktop")
    startup = _special_folder("Startup")
    _make_shortcut(desktop / PANEL_SHORTCUT, _launch_args("--panel"), "Панель управления PCFER")
    _make_shortcut(startup / SERVICE_SHORTCUT, _launch_args("--background"), "Фоновый сервис PCFER")
    if ipc("status") is None:
        start_service()
    notify("PCFER установлен.\n\n"
           f"• Ярлык панели: {desktop / PANEL_SHORTCUT}\n"
           f"• Автозапуск сервиса при входе в Windows: {startup / SERVICE_SHORTCUT}\n\n"
           "Персонаж появится в правом нижнем углу рабочего стола.")


def uninstall() -> None:
    if ipc("shutdown") is not None:
        time.sleep(1)
    for folder, name in ((_special_folder("Desktop"), PANEL_SHORTCUT),
                         (_special_folder("Startup"), SERVICE_SHORTCUT)):
        (folder / name).unlink(missing_ok=True)
    notify("PCFER удалён из автозапуска, ярлык панели удалён, сервис остановлен.")


