#  Панель управления (клиент сервиса)
# ══════════════════════════════════════════════════════════════════════════════
COMMAND_ACTIONS = ["say", "open_website", "open_app", "open_path", "keyboard",
                   "screenshot", "screen_record", "list_drives"]


def _int_or(text: Any, default: int) -> int:
    try:
        return max(1, int(str(text).strip()))
    except ValueError:
        return default


class JsonEditor(ctk.CTkToplevel):
    """Окно для редактирования списков в JSON. on_save получает текст и бросает ValueError при ошибке."""

    def __init__(self, parent, title: str, text: str, on_save) -> None:
        super().__init__(parent)
        self.title(title)
        self.geometry("600x540")
        self.on_save = on_save
        self.box = ctk.CTkTextbox(self, wrap="none", font=ctk.CTkFont(family="Consolas", size=13))
        self.box.pack(fill="both", expand=True, padx=12, pady=(12, 6))
        self.box.insert("1.0", text)
        self.status = ctk.CTkLabel(self, text="", text_color="#f28b82", anchor="w")
        self.status.pack(fill="x", padx=12)
        row = ctk.CTkFrame(self, fg_color="transparent")
        row.pack(fill="x", padx=12, pady=(0, 12))
        ctk.CTkButton(row, text="Сохранить и применить", command=self._save).pack(side="left")
        ctk.CTkButton(row, text="Закрыть", command=self.destroy, fg_color="#3a3d44",
                      hover_color="#4a4e57").pack(side="right")

    def _save(self) -> None:
        try:
            self.on_save(self.box.get("1.0", "end"))
        except (ValueError, TypeError, KeyError) as exc:
            self.status.configure(text=f"Ошибка: {exc}", text_color="#f28b82")
            return
        self.status.configure(text="Сохранено и применено.", text_color="#81c995")


class ControlPanel(ctk.CTk):
    COLORS = {"info": "#8ab4f8", "ok": "#81c995", "warn": "#fdd663",
              "error": "#f28b82", "user": "#d7aefb", "bot": "#78d9ec"}
    PREFIX = {"user": "🎤 Вы", "bot": "🤖 PCFER", "error": "✖ Ошибка", "warn": "⚠", "ok": "✔", "info": "•"}
    DEFAULT_VOICE = "Системный по умолчанию"
    LANGUAGES = ["ru-RU", "en-US", "uk-UA", "de-DE", "fr-FR", "es-ES"]
    BTN_GRAY = {"fg_color": "#3a3d44", "hover_color": "#4a4e57"}
    LOG_TAIL_BYTES = 30_000

    def __init__(self, settings: Settings, log: Logger) -> None:
        super().__init__()
        ctk.set_appearance_mode(settings.appearance)
        ctk.set_default_color_theme("blue")
        ctk.set_widget_scaling(settings.ui_scale)
        self.title("PCFER — панель управления")
        self.geometry("1120x780")
        self.minsize(960, 640)

        self.settings, self.log = settings, log
        self.voice_map: dict[str, str] = {}
        self.action_vars: dict[str, ctk.BooleanVar] = {}
        self._shown_provider = settings.provider
        self._status_busy = False
        self._log_pos = 0

        self._build_ui()
        self.protocol("WM_DELETE_WINDOW", self._on_close)
        self.after(100, self._poll)
        self.after(200, self._load_history)
        self.after(400, self._ensure_service)
        self.after(600, self._refresh_models)
        self.after(800, self._refresh_voices)
        self.after(1000, self._status_loop)
        log.info("Панель открыта. Сервис работает в фоне, панель можно закрыть в любой момент.")

    def report_callback_exception(self, exc, val, tb) -> None:
        self.log.error("Ошибка интерфейса:\n" + "".join(traceback.format_exception(exc, val, tb)))

